import * as T from './three.module.js';
import {WolfRig,savedWolfProject} from './wolf-rig.mjs?v=1';
export function attachWolf(g){
 g.userData.wolfLoading=true;
 WolfRig.load().then(rig=>{if(g.userData.disposed){rig.dispose();return;}for(const m of g.userData.monsterParts)m.visible=false;g.add(rig.group);g.userData.wolf=rig;g.userData.wolfLoading=false;g.userData.wolfSource='wolf-rig-edited.glb';g.userData.wolfPalette=rig.meshes.flatMap(m=>(Array.isArray(m.material)?m.material:[m.material]).map(material=>({material,color:material.color.clone()})));
 const segments=[[6,8,.24],[9,10,.2],[11,12,.11],[12,13,.08],[13,14,.075],[15,16,.11],[16,17,.08],[17,18,.075],[19,20,.13],[20,21,.09],[21,22,.08],[23,24,.13],[24,25,.09],[25,26,.08]];
 const mat=new T.MeshBasicMaterial();mat.visible=false;g.userData.wolfProxies=segments.map(([a,b,r])=>{const mesh=new T.Mesh(new T.BoxGeometry(1,1,1),mat);g.add(mesh);return {a,b,r,mesh};});g.userData.monsterParts=g.userData.wolfProxies.map(p=>p.mesh);updateProxies(g);
 }).catch(e=>{g.userData.wolfLoading=false;g.userData.wolfError=e.message;console.error('늑대 모델을 불러오지 못했습니다.',e);});
}
function updateProxies(g){g.updateMatrixWorld(true);const rig=g.userData.wolf,inv=g.matrixWorld.clone().invert();for(const p of g.userData.wolfProxies){const a=rig.bones[p.a].getWorldPosition(new T.Vector3()).applyMatrix4(inv),b=rig.bones[p.b].getWorldPosition(new T.Vector3()).applyMatrix4(inv),d=b.clone().sub(a);p.mesh.position.copy(a).add(b).multiplyScalar(.5);p.mesh.scale.set(p.r*2,Math.max(.05,d.length()+p.r),p.r*2);p.mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());}g.updateMatrixWorld(true);}
export function animateWolf(m,time){const rig=m.g.userData.wolf;if(!rig)return false;const id=m.frozen>0||m.knockdown>0?'idle':m.attackPhase==='windup'?'windup':m.attackPhase==='attack'?'attack':m.attackPhase==='recover'?'recover':m.moving?(m.locomotion||'run'):'idle';if(m.g.userData.wolfAction!==id){m.g.userData.wolfAction=id;m.g.userData.wolfStart=time;}const project=savedWolfProject(rig),clip=project.actions.find(a=>a.id===id),elapsed=time-m.g.userData.wolfStart;let t=elapsed;if(!clip.loop){const duration=id==='windup'?.65:id==='attack'?.42:1.3;t=Math.min(1,elapsed/duration)*(clip.frames-1)/clip.fps;}if(!(m.frozen>0))rig.apply(rig.sample(project,id,t));m.g.position.set(m.x,0,m.z);m.g.rotation.y=Math.atan2(m.dir.x,m.dir.z);for(const entry of m.g.userData.wolfPalette){entry.material.color.copy(entry.color);if(m.wind>0)entry.material.color.lerp(new T.Color(0xff6655),.25);if(m.hitFlash>0)entry.material.color.set(0xffffff);}updateProxies(m.g);return true;}
